// Track the real Vulkan descriptor calls as well as inherited image allocations.
// Pool accounting is checked against the declared layout, even on permissive drivers.
struct DescriptorTracker {
    struct Layout {std::map<uint32_t,VkDescriptorType>bindings;};
    struct Pool {uint32_t sets=0;std::map<VkDescriptorType,uint32_t>remaining;};
    struct Set {uint64_t pool=0,layout=0;std::map<uint32_t,uint64_t>samplers;};
    std::map<uint64_t,Layout>layouts;std::map<uint64_t,Pool>pools;
    std::map<uint64_t,Set>sets;std::map<uint64_t,uint32_t>samplers;
    uint32_t violations=0;bool pending=false;
}descriptors;
static auto descriptorLive(){uint32_t refs=0;for(const auto&s:descriptors.samplers)refs+=s.second;return std::array<size_t,4>{descriptors.layouts.size(),descriptors.pools.size(),descriptors.sets.size(),refs};}
